import{_ as r,o as n,c as t,a3 as h}from"./chunks/framework.z_KJ15Ep.js";const o=JSON.parse('{"title":"Fächer und Kurse einer Schülergruppe zuweisen","description":"","frontmatter":{},"headers":[],"relativePath":"schild3/faecher-kurse.md","filePath":"schild3/faecher-kurse.md"}'),a={name:"schild3/faecher-kurse.md"};function s(i,e,c,u,d,l){return n(),t("div",null,[...e[0]||(e[0]=[h('<h1 id="facher-und-kurse-einer-schulergruppe-zuweisen" tabindex="-1">Fächer und Kurse einer Schülergruppe zuweisen <a class="header-anchor" href="#facher-und-kurse-einer-schulergruppe-zuweisen" aria-label="Permalink to &quot;Fächer und Kurse einer Schülergruppe zuweisen&quot;">​</a></h1><p>Weisen Sie vorbereitete Fächer und Kurse einer gefilterten Schülergruppe zu. Prüfen Sie vor dem Start den Lernabschnitt und unterscheiden Sie Ergänzen, Ändern und Löschen.</p><h2 id="unterricht-zuweisen" tabindex="-1">Unterricht zuweisen <a class="header-anchor" href="#unterricht-zuweisen" aria-label="Permalink to &quot;Unterricht zuweisen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aufgabe</th><th>Anleitung</th></tr></thead><tbody><tr><td>Vorbereitete Stundentafeln übernehmen</td><td><a href="/schild3/suchen-gruppenprozesse/stundentafeln-zuweisen-gruppenprozesse-faecher.html">Stundentafeln zuweisen</a></td></tr><tr><td>Fachbelegungen in einer Tabelle bearbeiten</td><td><a href="/schild3/suchen-gruppenprozesse/faecher-zuweisen-tabellarisch-gruppenprozesse-faecher.html">Fächer tabellarisch zuweisen</a></td></tr><tr><td>Ein einzelnes Fach hinzufügen</td><td><a href="/schild3/suchen-gruppenprozesse/einzelne-faecher-bei-schuelern-hinzufuegen-gruppenprozesse-faecher.html">Einzelne Fächer ergänzen</a></td></tr><tr><td>Kurse einer gefilterten Gruppe zuweisen</td><td><a href="/schild3/suchen-gruppenprozesse/kurse-zuweisen-gruppenprozesse-faecher.html">Kurse zuweisen</a></td></tr></tbody></table><p>Die erforderlichen Kataloge und Vorlagen werden unter <a href="/schild3/unterricht-kataloge.html">Klassen und Unterricht</a> eingerichtet.</p><h2 id="vorhandenen-unterricht-pflegen" tabindex="-1">Vorhandenen Unterricht pflegen <a class="header-anchor" href="#vorhandenen-unterricht-pflegen" aria-label="Permalink to &quot;Vorhandenen Unterricht pflegen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aufgabe</th><th>Anleitung</th></tr></thead><tbody><tr><td>Bestehenden Klassenunterricht bearbeiten</td><td><a href="/schild3/suchen-gruppenprozesse/klassenunterrichte-bearbeiten-gruppenprozesse-faecher.html">Klassenunterricht bearbeiten</a></td></tr><tr><td>Fachdetails ändern oder gezielt leeren</td><td><a href="/schild3/suchen-gruppenprozesse/details-zu-faechern-bei-schuelern-aendern-gruppenprozesse-faecher.html">Fachdetails ändern</a></td></tr><tr><td>Fächer nachträglich aus einem früheren Abschnitt holen</td><td><a href="/schild3/suchen-gruppenprozesse/faecher-aus-vorherigem-abschnitt-holen-gruppenprozesse-faecher.html">Fächer übernehmen</a></td></tr><tr><td>Fächerfolge am BK aktualisieren</td><td><a href="/schild3/suchen-gruppenprozesse/faecher-in-leistungsdaten-neu-sortieren-gruppenprozesse-faecher.html">Fächer am BK sortieren</a></td></tr><tr><td>Doppelte Fachbelegungen bereinigen</td><td><a href="/schild3/suchen-gruppenprozesse/doppelte-faecher-loeschen-gruppenprozesse-faecher.html">Doppelte Fächer entfernen</a></td></tr></tbody></table><h2 id="facher-entfernen" tabindex="-1">Fächer entfernen <a class="header-anchor" href="#facher-entfernen" aria-label="Permalink to &quot;Fächer entfernen&quot;">​</a></h2><p>Für einzelne Fächer nutzen Sie <a href="/schild3/suchen-gruppenprozesse/einzelne-faecher-bei-schuelern-loeschen-gruppenprozesse-faecher.html">die gezielte Löschung</a>. Der Gruppenprozess <a href="/schild3/suchen-gruppenprozesse/alle-faecher-bei-schuelern-loeschen-gruppenprozesse-faecher.html">Alle Fächer löschen</a> entfernt die gesamte Fachbelegung der Gruppe mit den Leistungsdaten. Beachten Sie die im Artikel beschriebenen Folgen, bevor Sie die Ausführung bestätigen.</p>',9)])])}const f=r(a,[["render",s]]);export{o as __pageData,f as default};
